      "proposed_laureates": [
        "Alan H. Guth",
        "Andrei Linde",
        "Viatcheslav Mukhanov"
      ],
      "assessment": {
        "nobel_worthiness": "Inflation and the quantum origin of cosmic structure supplied a compelling physical account of the early universe and made testable predictions central to modern cosmology.",
        "attribution": "Guth initiated inflation, Linde developed its viable modern forms, and Mukhanov established the quantum mechanism for primordial structure.",
        "maturity": "CMB and large-scale-structure observations strongly support the central framework after decades of scrutiny.",
        "uncertainties": [
          "No direct primordial gravitational-wave signature has yet selected a specific inflationary realization.",
          "Early conceptual credit is broader than three names."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B036",
      "proposed_laureates": [
        "Daniel J. Eisenstein",
        "Matthew Colless",
        "Shaun Cole"
      ],
      "assessment": {
        "nobel_worthiness": "Baryon acoustic oscillations transformed an early-universe relic into a robust standard ruler for charting cosmic expansion.",
        "attribution": "The listed scientists represent the decisive theoretical interpretation and major survey demonstrations, although the achievement rests on extensive collaborations.",
        "maturity": "Repeated surveys have made BAO a mature and exceptionally useful precision-cosmology method.",
        "uncertainties": [
          "The division between foundational theoretical and survey credit needs careful expert examination."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B031",
      "proposed_laureates": [
        "Heino Falcke",
        "Ramesh Narayan",
        "Sheperd S. Doeleman"
      ],
      "assessment": {
        "nobel_worthiness": "Horizon-scale imaging of black holes is an extraordinary observational achievement that brings strong-gravity physics into direct view.",
        "attribution": "Falcke, Narayan and Doeleman capture key conceptual, theoretical and instrumental leadership, while the result was necessarily a large collaboration.",
        "maturity": "The M87 and Galactic-centre results, with independent analysis pipelines and follow-up observations, establish a durable achievement.",
        "uncertainties": [
          "The image tests compact-object and accretion predictions more directly than it uniquely proves every aspect of a classical event horizon.",
          "Collaboration credit is difficult to compress into three people."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B046",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Lyman A. Page"
      ],
      "assessment": {
        "nobel_worthiness": "WMAP converted the cosmic microwave background into a precision probe of the universe's contents, geometry and primordial fluctuations.",
        "attribution": "Bennett and Page were central to the mission and Spergel to its cosmological interpretation; broader mission credit remains substantial.",
        "maturity": "Its conclusions have been extensively confirmed and refined by later measurements.",
        "uncertainties": [
          "The result is part of a longer observational chain involving COBE and Planck."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B019",
      "proposed_laureates": [
        "Michael V. Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "Geometric phase and the Aharonov-Bohm effect revealed that quantum phase has physically measurable, globally nontrivial consequences across physics.",
        "attribution": "Berry and Aharonov are clear intellectual figureheads for the two linked effects, though associated co-discoverers and experimental confirmations require review.",
        "maturity": "Both phenomena are deeply established experimentally and conceptually, with wide consequences in quantum and condensed-matter physics.",
        "uncertainties": [
          "The candidate combines two distinct discoveries with partially different histories of credit."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B060",
      "proposed_laureates": [
        "Martin J. Rees",
        "Sandra M. Faber",
        "Simon D. M. White"
      ],
      "assessment": {
        "nobel_worthiness": "Cold dark matter and hierarchical formation provided the organizing framework for interpreting the growth of cosmic structure.",
        "attribution": "Faber, White and Rees made major formative contributions, but the framework emerged through a broad community and related observational evidence.",
        "maturity": "The large-scale framework has been highly successful over several decades.",
        "uncertainties": [
          "The microscopic nature of dark matter remains unknown.",
          "Small-scale tensions and diffuse historical attribution limit a clean prize formulation."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B024",
      "proposed_laureates": [
        "Brian D. Metzger",
        "Daniel Kasen",
        "Edo Berger"
      ],
      "assessment": {
        "nobel_worthiness": "The association of neutron-star mergers with kilonovae and heavy-element production is a major multi-messenger insight into cosmic chemical origins.",
        "attribution": "Metzger and Kasen supplied decisive theoretical groundwork and Berger important observational leadership, but the scientific and collaboration-wide credit is extensive.",
        "maturity": "The neutron-star merger observations gave striking confirmation of the basic picture.",
        "uncertainties": [
          "The quantitative share of r-process production across astrophysical sites remains unsettled.",
          "The candidate's credit boundaries need expert review."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B038",
      "proposed_laureates": [
        "Alexander M. Polyakov",
        "Edward Witten",
        "Juan Maldacena"
      ],
      "assessment": {
        "nobel_worthiness": "Gauge-gravity duality is one of the most profound theoretical ideas in modern high-energy physics and has reshaped several fields.",
        "attribution": "Maldacena made the decisive explicit conjecture, building on essential antecedents from Polyakov, Witten and a wider string-theory community.",
        "maturity": "Its internal theoretical development and applications are extensive.",
        "uncertainties": [
          "There is no direct empirical confirmation in nature of the duality as a description of our universe.",
          "Its broad conceptual lineage makes attribution especially difficult."
        ]
      }
    }
  ]
